	'messages:permissionserrorstext-withaction' => 'jv:Panjenengan ora diidinaké $2 amarga {{PLURAL:$1|alasan|alasan}} ing ngisor iki:',
	'messages:recreate-moveddeleted-warn' => 'jv:<strong>Pélik: Panjenengan nggawé manèh kaca kang tau kabusak.</strong>

